inline constexpr unsigned demoFontAtlasBytes = sizeof(demoGrid2Bits)+sizeof(demoGrid3Bits)+sizeof(demoLabel12Bits)+sizeof(demoLabel18Bits);
static_assert(demoFontAtlasBytes < 1536u*1024u, "Keep all typefaces below 1.5 MiB");
static_assert(demoLabel12Pixels==sizeof(uiFont12Pixels) && demoLabel18Pixels==sizeof(uiFont18Pixels), "Label atlas layout changed");

// The atlases are two-level masks packed one bit per pixel (tools/fonts/pack_demo_atlases.py):
// pixel i of a face is bit (i & 7) of byte i >> 3. A glyph is a face plus the index of its first
// pixel, read through alpha() — 0 or 255, exactly the values the unpacked atlases held.
struct DemoAlpha {
    const uint8_t* bits = nullptr;   // the face; null: no custom typeface for this text
    uint32_t start = 0;              // first pixel of the glyph (grid) or of the atlas (labels)
    explicit operator bool() const { return bits != nullptr; }
    uint8_t alpha(uint32_t index) const {
        const uint32_t i = start + index;
        return ((bits[i >> 3] >> (i & 7)) & 1u) ? 255 : 0;
    }
};
inline DemoAlpha demo_grid_pixels(int style,int font_scale,uint32_t cp) {
    if(style<1 || style>16 || cp<32 || cp>126)return {};
    if(font_scale==2)return {demoGrid2Bits[style-1],(cp-32)*110u};
    if(font_scale==3)return {demoGrid3Bits[style-1],(cp-32)*255u};
    return {};
}
inline DemoAlpha demo_label_pixels(int style,int size) {
    if(style<1 || style>16)return {};
    // As label_font: 14-px atlas up to 14 and for the doubled title size (26 and up), 21 px between.
    return {size>=15 && size<26?demoLabel18Bits[style-1]:demoLabel12Bits[style-1],0u};
}
